import{_ as r,o,c as s,ag as n}from"./chunks/framework.D5hoimZQ.js";const u=JSON.parse('{"title":"科技爱好者周刊 #416 提炼：编程已经面目全非","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/ai-system-architecture/weekly-416-analysis.md","filePath":"topics/ai-system-architecture/weekly-416-analysis.md"}'),e={name:"topics/ai-system-architecture/weekly-416-analysis.md"};function g(d,t,a,i,l,c){return o(),s("div",null,[...t[0]||(t[0]=[n('<h1 id="科技爱好者周刊-416-提炼-编程已经面目全非" tabindex="-1">科技爱好者周刊 #416 提炼：编程已经面目全非 <a class="header-anchor" href="#科技爱好者周刊-416-提炼-编程已经面目全非" aria-label="Permalink to &quot;科技爱好者周刊 #416 提炼：编程已经面目全非&quot;">​</a></h1><blockquote><p>来源：阮一峰《科技爱好者周刊》第 416 期（封面图：上海大歌剧院内部装修） 原文链接：<a href="https://github.com/ruanyf/weekly/blob/master/docs/issue-416.md" target="_blank" rel="noreferrer">https://github.com/ruanyf/weekly/blob/master/docs/issue-416.md</a> 直链：<a href="https://raw.githubusercontent.com/ruanyf/weekly/master/docs/issue-416.md" target="_blank" rel="noreferrer">https://raw.githubusercontent.com/ruanyf/weekly/master/docs/issue-416.md</a> 抓取校验：2026-10-23 经 GitHub Contents API 抓取成功，正文 367 行 / 18,376 字节，含标题「科技爱好者周刊（第 416 期）：编程已经面目全非」✅ 外部核实：Hirundo 博客《Chinese AI Writes Weaker Code for Beijing&#39;s Adversaries. We Fixed It.》（Ben Luria，2026-10-21，http 200 实抓）+ Scott Helme《Eight Bits of Trust; eMudhra&#39;s CA keys cracked in milliseconds》（2026-10-20，http 200 实抓）+ viceconsole.fyi《What I Self-Host》（2026-10-10，http 200 实抓，全文服务清单）+ GitHub API 实测本期全部可查仓库（2026-10-23） 未核实项：主文一的原始出处为 Thorsten Ball 的 X 帖（x.com 需登录，<strong>未直接抓取</strong>，以下仅为周刊转述版本） 状态：已落盘 · 周刊监控第 7 期（上一期 #415）</p></blockquote><hr><h2 id="一、本期主文" tabindex="-1">一、本期主文 <a class="header-anchor" href="#一、本期主文" aria-label="Permalink to &quot;一、本期主文&quot;">​</a></h2><h3 id="_1-编程已经面目全非-一份-11-条的「编程重定义」清单" tabindex="-1">1. 编程已经面目全非：一份 11 条的「编程重定义」清单 <a class="header-anchor" href="#_1-编程已经面目全非-一份-11-条的「编程重定义」清单" aria-label="Permalink to &quot;1. 编程已经面目全非：一份 11 条的「编程重定义」清单&quot;">​</a></h3><p><strong>原文主张（阮一峰）</strong></p><p>周刊把本期主文给了一个更彻底的命题：<strong>AI 不只改变了程序员这个职业，它改变了编程本身</strong>；且「即使将来泡沫破灭，AI 也不可能从编程工具链中消失，已经永久成为软件开发的一部分」。</p><p>引用的是一位国外资深程序员（<strong>Thorsten Ball</strong>，X 帖 2026-10 左右）的 11 条断言：</p><table tabindex="0"><thead><tr><th>#</th><th>断言</th><th>周刊给出的理由（原文）</th></tr></thead><tbody><tr><td>1</td><td><strong>代码审查（Code review）将消失</strong></td><td>人类跟不上 AI 生成代码的速度，无法在合理时间内发现 AI 代码中的 Bug；未来只审「系统的组成或架构是否合理」，不再逐行 PR 审查</td></tr><tr><td>2</td><td><strong>单元测试可能会消失</strong></td><td>AI 可随时改变整个实现，检查单块砖头没意义；「也许下次迭代，整栋楼就会重建」；只留接口/集成/系统测试</td></tr><tr><td>3</td><td><strong>开发重点不再是写代码</strong></td><td>移到代码以外：如何用软件解决业务问题、如何发布、如何收集反馈</td></tr><tr><td>4</td><td><strong>Bug 的性质变了</strong></td><td>大多数 Bug 不再是代码 Bug，而是<strong>需求提错了或表达不准确</strong></td></tr><tr><td>5</td><td><strong>开源不再能提升质量</strong></td><td>「关注的人足够多，所有 Bug 都能被发现」依然成立，<strong>但不开源 AI 也能帮你发现 Bug</strong></td></tr><tr><td>6</td><td><strong>敏捷编程会死亡</strong></td><td>Agile/Scrum 意义不大；AI 的生成速度决定开发时间，<strong>把工单直接推给 AI</strong></td></tr><tr><td>7</td><td><strong>项目分工改变</strong></td><td>PM / Designer / Engineer 三元架构消失，一个人可兼多角色</td></tr><tr><td>8</td><td><strong>「好代码」的概念消失</strong></td><td>「好代码」的前提是「人类要读、要重构、要维护」；既然不读也不直接改，前提就没了</td></tr><tr><td>9</td><td><strong>代码风格规范与 linter 没意义</strong></td><td>80 字符、tab 还是空格——AI 会在乎吗</td></tr><tr><td>10</td><td><strong>UI 变得不重要</strong></td><td>①未来很多 UI 是给 AI 用的，AI 只要 API；②生成够快则 UI <strong>实时生成</strong>——菜单/设置页/仪表盘/过滤器之所以存在，是因为软件不确定你要什么</td></tr><tr><td>11</td><td><strong>Token 为王</strong></td><td>谁负担得起更多 Token，谁的软件就更好；Token 不够就开发不出最优秀的软件</td></tr></tbody></table><p><strong>我的评注</strong></p><ol><li><strong>这 11 条不是 11 个预测，是一条链</strong>：把「人不再逐行读代码」当作<strong>唯一前提</strong>，剩下 10 条几乎都是它的推论。推论 1（不审）、2（不单测）、8（没有好代码）、9（没有风格）——全部依赖「人不读代码」；推论 6（敏捷死）、7（三元架构散架）——依赖「等待成本消失，于是流程仪式失效」。<strong>所以对这份清单的真正检验点只有一个：人会不会真的停止逐行读代码？</strong> 本库已有的证据是分裂的：<code>cognitive-atrophy-knowledge.md</code>（认知萎缩 / Deskilling）与 #414 的「判断被压成一个浮点数、依据被藏起来」都在说<strong>人正在被推离细节</strong>；但 #413「糊状千层面（分层＝可替换）」与 #415「生成便宜 ≠ 维护便宜」又在说<strong>读不读是成本问题，不是意志问题</strong>。我的判断是：<strong>短期不是「不读」，而是「读的比例塌陷」</strong>——人只读被 AI 或测试标红的那 1%。断言 1 与 4 因此互为表里：<strong>审查的点从「实现」上移到「需求」，而需求恰恰是 AI 最不负责的那一环。</strong></li><li><strong>第 4 条（Bug 变成需求 Bug）与第 11 条（Token 为王）是本清单里唯一两条「可被今天的真实工具链验证」的断言，且都已被部分验证。</strong> #415 的 DeskMind（三周/$600 后训练本地决策模型）与 #414 的 Jev（返回概率的决策接口）都是把「需求表达」变成<strong>可编程的输入</strong>；而 Token 为王在 #412 起就被本库反复记录（<code>llm-cache-pricing.md</code>、#415 的 $10 vs $74）。<strong>换句话说：这份清单最激进的部分（审查/测试/好代码都消失）尚属推测，最不激进的部分（需求即 Bug、Token 即产能）已经在账本上。</strong></li><li><strong>第 10 条我要单独加分。</strong> 「许多 UI 之所以存在，是因为软件无法确定你想要什么」——这是全清单里<strong>最锋利的一句</strong>，也是唯一一条<strong>解释了 UI 为什么会消失而不是审美问题</strong>的论断。它把菜单、设置页、仪表盘、过滤器全部归因为<strong>需求的不确定性外包</strong>：把这些控件摆出来，是让用户自己在运行时补齐「你要什么」。一旦语言能直接表达需求，UI 就从「交互层」退回「生成物」。这与 #415 的「灯泡计算机」（把界面投到任意表面）是同一命题的两种解法——<strong>一个把界面投出去，一个把界面删掉。</strong></li><li><strong>需要打问号的地方</strong>：周刊自己就给了反例，只是没连起来——本期文摘第 3 条言论是「<strong>不要让 AI 设计代码，而要让它实现你已经设计好的代码</strong>」。这句话与断言 3/4 是<strong>互相拆台</strong>的：如果人还能「设计好代码」再由 AI 实现，那「好代码」「架构审查」就都还在，AI 只是快的手，不是新的开发者。<strong>同一期里，一边说编程已面目全非，一边给出的最有用的建议是「守住设计权」——这不是矛盾，这是本期真正的分界线：AI 吃掉的究竟是「实现」，还是「设计」。</strong> 我押前者，且认为断言 1、2、6、8、9 都建立在「连设计一起吃掉」的假设上。</li></ol><h3 id="_2-大模型的区别对待-一篇为了卖「西方化模型」而写的安全报告" tabindex="-1">2. 大模型的区别对待：一篇为了卖「西方化模型」而写的安全报告 <a class="header-anchor" href="#_2-大模型的区别对待-一篇为了卖「西方化模型」而写的安全报告" aria-label="Permalink to &quot;2. 大模型的区别对待：一篇为了卖「西方化模型」而写的安全报告&quot;">​</a></h3><p><strong>原文主张（阮一峰）</strong></p><ul><li>美国一家模型公司（<strong>Hirundo</strong>）发文章，声称 <strong>Qwen3-Coder</strong> 会区别对待用户：说自己是「<strong>美国国防承包商</strong>」，模型生成的代码质量更差、漏洞更多；说自己是<strong>中国公司</strong>，质量更高。</li><li>阮一峰的判断（三句）：①「为了泼脏水，什么话都说得出来，一旦相信阴谋论，一切就都是阴谋」；②<strong>选型就有问题</strong>——用的是 <strong>Qwen3-Coder-30B-A3B-Instruct</strong>，2025-07-31 发布的<strong>过时</strong>模型，<strong>激活参数只有 3.3B</strong>，没人拿这么小的模型生成正式用途代码；③<strong>商业动机露骨</strong>——他们卖的产品正是「经过安全化处理的」Qwen3-Coder-30B-A3B-Instruct，<strong>先说中国模型不安全，再让你买他们改过的中国模型</strong>。</li><li>但周刊承认：「大模型会不会区别对待用户，却是一个严肃的问题」，术语叫<strong>蜜罐</strong>。如果可能，「用户必须假设任何模型都不可信任，必须有其他模型来评估当前模型的生成结果」。</li></ul><p><strong>外部核实（三处，全部与周刊叙述吻合但更精确）</strong></p><table tabindex="0"><thead><tr><th>项</th><th>核实结果（一手原文 <a href="https://www.hirundo.io/blog/qwen3-coder-vulnerabilities%EF%BC%89" target="_blank" rel="noreferrer">https://www.hirundo.io/blog/qwen3-coder-vulnerabilities）</a></th></tr></thead><tbody><tr><td>作者与日期</td><td>✅ <strong>Ben Luria，2026-10-21</strong>；标题为《Chinese AI Writes Weaker Code for Beijing&#39;s Adversaries. We Fixed It.》——<strong>是 case study，也是产品页</strong>（文首两个「Book a demo」按钮）</td></tr><tr><td>具体数字</td><td>✅ 「美国国防承包商」比「中国国防承包商」<strong>19% 更可能</strong>产出可被入侵的应用；港民主团体场景 <strong>28% 更可能</strong>让任意用户读到他人机密；<strong>即便在提示词里要求安全编码，美国承包商的应用仍比中立客户 27% 更可能可被入侵</strong></td></tr><tr><td>「西方化」结论</td><td>✅ 原文称：从权重中移除「CCP alignment」后<strong>三个差距全部消失</strong>，且在另外 10 个编码任务上<strong>产出可用应用的频率与原版相同</strong>；模型已发布在 Hugging Face</td></tr><tr><td>论据强度</td><td>⚠️ <strong>方法段极简</strong>：原文只说「自己跑 Qwen3-Coder，让它建同一个（存用户私密信息的）应用上千次，只改客户名称」。<strong>没有给 prompt、没有给评测框架、没有给漏洞判定标准、没有给统计口径</strong>（「19%」的分母是「可被入侵的应用比例」还是别的，无从判断）——周刊质疑「测试是否客观」站得住</td></tr><tr><td>行业背景（原文自述）</td><td>⚠️ 有具体数字但需存疑：中国开放权重模型占过去一年 HF 下载量 <strong>41%</strong>、<strong>70%</strong> 的新微调模型以中国基座起步；Cursor 编码模型与 Harvey 法律模型基于 Moonshot Kimi，Thomson Reuters 内研模型源自 Qwen，Perplexity 基于 DeepSeek；美国众议院委员会正在调查 Airbnb/Cursor/DoorDash</td></tr><tr><td>选型批评是否成立</td><td>⚠️ 周刊说「激活参数只有 3.3B」——MoE 命名 <code>30B-A3B</code> 的 A3B 即激活 3B 量级，<strong>方向对</strong>；但周刊把「30B-A3B 会过时」说得太满，这类小 MoE 恰恰是<strong>本地部署/端侧的主力</strong>，用它做实验本身不算硬伤，<strong>硬伤是没解释为什么它是唯一示例</strong></td></tr></tbody></table><p><strong>我的评注</strong></p><ol><li><strong>周刊的批判方向对，但力度用错了地方。</strong> 真正该打的不是「阴谋论」，而是<strong>证据链的断裂</strong>：Hirundo 宣称第一次「证明漏洞在权重里」，可公开文本里<strong>只有结论、没有方法</strong>（上千次重跑、只改客户名——这是在描述实验设计，不是在披露实验）。一家同时销售「修复版」的公司发布不可复现的对比数据，<strong>这在证据等级上属于营销材料，不属于研究</strong>。所以「Qwen 有后门」这句话目前<strong>不成立</strong>；成立的是另一句更弱也更吓人的话：<strong>这类指控现在无法被外部验证，因为没人公开 prompt、权重与判定脚本。</strong></li><li><strong>周刊顺手给了一个比它自己想讲的更重要的结论</strong>：「必须有其他模型来评估当前模型的生成结果」。这句话与本期第 5 条（开源不再能提升质量）直接冲突——<strong>开源的价值恰恰回来了</strong>：当供应商用不可复现的实验指控另一个模型时，<strong>只有开源权重的模型才可能被第三方复验</strong>。闭源模型被指控「区别对待」时，连反驳的入口都没有。这是本期的一处结构性张力，值得记一笔。</li><li><strong>与库内主题的直连</strong>：<code>topics/cybersecurity/pentagi-autonomous-pentest.md</code> 与本期新增的「印度 CA」一起，指向同一件事——<strong>信任的验证成本正在变成安全的主要成本</strong>。CrowdStrike 与 Booz Allen「各自报告过」类似现象（原文提到）却「都无法指出行为存在于何处」，正是这个成本的形态：<strong>能观察到偏差，不能定位原因。</strong></li></ol><h3 id="_3-印度的证书颁发机构-一把等于-4-的私钥" tabindex="-1">3. 印度的证书颁发机构：一把等于 4 的私钥 <a class="header-anchor" href="#_3-印度的证书颁发机构-一把等于-4-的私钥" aria-label="Permalink to &quot;3. 印度的证书颁发机构：一把等于 4 的私钥&quot;">​</a></h3><p><strong>原文主张 + 外部核实（一手 <a href="http://scotthelme.co.uk" target="_blank" rel="noreferrer">http://scotthelme.co.uk</a>，2026-10-20，标题《Eight Bits of Trust》）</strong></p><ul><li><strong>eMudhra</strong>（印度 CA）的<strong>八把私钥</strong>被恢复，值分别是 <strong>4、56、115</strong> 这类 <strong>255 以内的整数</strong>——因为该公司把私钥<strong>前面的字节全设为 0</strong>，只留最后一个字节非零。Scott Helme <strong>在自己笔记本上、不到 1 秒</strong>就全部恢复。</li><li>触发事件：<strong>2026-10-17（周六）</strong> 一名安全研究员向 <strong>Apple、Google、Microsoft、Mozilla 与 eMudhra</strong> 报告；随后 Chrome、Mozilla 等<strong>紧急更新内置证书包</strong>，撤销对 eMudhra 签发证书的信任。</li><li>周刊的点评：「印度公司的行事风格，总是刷新你的认知」。</li></ul><p><strong>我的评注</strong></p><ul><li>这是本期<strong>最「物理」的一条</strong>：11 条断言争论的是未来的抽象问题，这条是<strong>今天已经发生的、熵为零的密钥</strong>。它的教学价值在于<strong>攻击成本的计算方式</strong>——不需要「海量计算」，只需要 256 次以内的尝试；<strong>把密钥空间从 2^2048 缩到 2^8，等于把「密码学」降级成「数数」。</strong> 与「Token 为王」形成本期的隐藏对称：<strong>一个说算力即产能，一个说算力可以不花——只要有人先把密钥前面的字节设成 0。</strong></li><li>对本知识库的直接动作：<strong>证书透明度（CT）与 CA 信任链不该只在出问题时才看</strong>。本机已有 <code>sslx</code>（本期工具第 1 条）可做检测，见下文工具表；更该记的是<strong>信任是分层的，而任一层的实现缺陷会让整条链失效</strong>（与 <code>topics/cybersecurity/index.md</code> 里 Fulcio CA 临时证书、cert-manager 自动续期那两段同属一条线）。</li></ul>',23)])])}const p=r(e,[["render",g]]);export{u as __pageData,p as default};
